blocks = B[:12] + [physionet_population] + B[12:35] + q15methods + B[35:65] + q15results + discussion + supp
blocks = revise_blocks(blocks)
ref_data = json.loads((OUT / 'references.json').read_text())
refs = ref_data['references'] if isinstance(ref_data, dict) else ref_data

def ref_text(r):
    if r.get('formatted_citation'): return r['formatted_citation'].replace(', ;', ';')
    authors = r.get('authors', [])
    if isinstance(authors, list): authors = '; '.join(str(a) for a in authors)
    venue = r.get('venue', r.get('journal', ''))
    details = str(r.get('volume', ''))
    if r.get('issue'): details += '(' + str(r['issue']) + ')'
    pages = str(r.get('pages_or_article', r.get('pages', '')))
    if pages: details += (', ' if details else '') + pages
    if r.get('version'): details = 'version ' + str(r['version'])
    return f'{authors} ({r["year"]}). {r["title"]}. {venue}' + (', ' + details if details else '') + '. ' + r.get('url', '')

# Conventional reference numbering follows first appearance. Source participant
# groups are spelled out first so their brackets cannot be mistaken for citations.
for block in blocks:
    if block['type'] == 'paragraph':
        block['text'] = block['text'].replace('[1,2], [3,4], [5,6], and [7,8,9]', 'people 1–2, 3–4, 5–6, and 7–9')
pattern = re.compile(r'\[(\d{1,2}(?:\s*[,–-]\s*\d{1,2})*)\]')
first_seen = []
def expand_ids(text):
    ids = []
    for piece in text.split(','):
        ends = re.split('[–-]', piece.strip())
        ids.extend(range(int(ends[0]), int(ends[-1]) + 1))
    return ids
for block in blocks:
    for match in pattern.finditer(block.get('text', '') + block.get('caption', '') + block.get('note', '')):
        for number in expand_ids(match.group(1)):
            assert 1 <= number <= len(refs)
            if number not in first_seen: first_seen.append(number)
assert len(first_seen) == len(refs), 'Every listed reference must be cited.'
mapping = {old_number: new_number for new_number, old_number in enumerate(first_seen, 1)}
for block in blocks:
    for field in ['text', 'caption', 'note']:
        if field in block:
            block[field] = pattern.sub(lambda m: '[' + ','.join(str(mapping[n]) for n in expand_ids(m.group(1))) + ']', block[field])
refs = [refs[n - 1] for n in first_seen]
(OUT / 'evidence/reference_order.json').write_text(json.dumps({'source_to_manuscript': mapping, 'ordered_keys': [r['key'] for r in refs]}, indent=2) + '\n')

aff = json.loads((OUT / 'evidence/affiliation_verification.json').read_text())
content = {'title': TITLE, 'subtitle': SUBTITLE,
           'authors': [{'name': 'Ziyuan Zhu', 'chinese_name': '朱子元', 'corresponding': True,
                        'affiliation': aff['recommended_affiliation_en'], 'email': 'zzy2630816871@gmail.com'}],
           'date': '7 October 2026', 'blocks': blocks, 'references': [ref_text(r) for r in refs],
           'reference_keys': [r['key'] for r in refs], 'new_fits': 0, 'new_checkpoint_inference': 0,
           'status': 'structured_revision_q16_complete_core_author_declarations_confirmed_final_approval_pending'}
(OUT / 'manuscript_content.json').write_text(json.dumps(content, indent=2, ensure_ascii=False) + '\n')
print(json.dumps({'blocks': len(blocks), 'references': len(refs), 'new_fits': 0}))
